select '01 fondatrice : création de 2 publications en brouillon', pg_temp.essai(:'F', $q$insert into bsh_communications(id,titre,contenu,type,cible,statut,espace,date_programmee,notes_internes) values ('a0000000-0000-0000-0000-000000000001','Secret du 1er','Texte','publication','tous','brouillon','chaine','2026-12-01T11:00:00Z','note interne P1'),('a0000000-0000-0000-0000-000000000002','Secret du 2','Texte','publication','tous','brouillon','cercle','2026-12-02T11:00:00Z','note interne P2')$q$);
select '02 programmation sans validation refusée par la base', pg_temp.essai(:'F', $q$update bsh_communications set statut='programme' where id='a0000000-0000-0000-0000-000000000001'$q$) = 'refusé';
select '03 validation puis programmation acceptées', pg_temp.essai(:'F', $q$update bsh_communications set statut='valide', valide_le=now(), valide_par=auth.uid() where id in ('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000002')$q$) = 'accepté' and pg_temp.essai(:'F', $q$update bsh_communications set statut='programme' where id in ('a0000000-0000-0000-0000-000000000001','a0000000-0000-0000-0000-000000000002')$q$) = 'accepté';
select '04 « publié » sans preuve refusé, même pour la fondatrice', pg_temp.essai(:'F', $q$update bsh_communications set statut='publie' where id='a0000000-0000-0000-0000-000000000001'$q$) = 'refusé';
