select '06 mission : H1 titulaire, H2 remplaçante, ressources autorisées', pg_temp.essai(:'F', $q$insert into bsh_ressources(id,titre,univers,type,statut_validation,valide_le,droits,empreinte) values ('c0000000-0000-0000-0000-000000000001','Affiche validée','secret_agenda','affiche','valide',now(),'proprietaire','aa11'),('c0000000-0000-0000-0000-000000000002','Visuel droits à vérifier','secret_agenda','affiche','valide',now(),'a_verifier','bb22'),('c0000000-0000-0000-0000-000000000003','Non autorisée','commun','texte','valide',now(),'proprietaire',null);
 insert into bsh_animations(id,nom,espace) values ('d0000000-0000-0000-0000-000000000001','Quiz Noël','cercle');
 insert into bsh_missions(id,hote_id,remplacant_id,titre,date_mission,espace,communication_id,animation_id,consignes,ressources) values ('e0000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','Animer le 2','2026-12-02T11:00:00Z','cercle','a0000000-0000-0000-0000-000000000002','d0000000-0000-0000-0000-000000000001','Consignes','{c0000000-0000-0000-0000-000000000001,c0000000-0000-0000-0000-000000000002}')$q$) = 'accepté';
select '07 remplaçant identique au titulaire refusé', pg_temp.essai(:'F', $q$insert into bsh_missions(hote_id,remplacant_id,titre) values ('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001','x')$q$) = 'refusé';
select '08 H1 titulaire : voit sa mission, sa publication, son animation ; pas la publication P1', pg_temp.compte(:'U1', $q$select count(*) from bsh_missions$q$) = 1 and pg_temp.compte(:'U1', $q$select count(*) from bsh_communications$q$) = 1 and pg_temp.compte(:'U1', $q$select count(*) from bsh_animations$q$) = 1;
select '09 H2 remplaçante : voit la même mission et ses éléments', pg_temp.compte(:'U2', $q$select count(*) from bsh_missions$q$) = 1 and pg_temp.compte(:'U2', $q$select count(*) from bsh_communications where id='a0000000-0000-0000-0000-000000000002'$q$) = 1 and pg_temp.compte(:'U2', $q$select count(*) from bsh_animations$q$) = 1;
select '10 ressources : l''hôte ne voit que la ressource validée, aux droits établis, autorisée dans sa mission', pg_temp.compte(:'U1', $q$select count(*) from bsh_ressources$q$) = 1 and pg_temp.compte(:'U1', $q$select count(*) from bsh_ressources where id='c0000000-0000-0000-0000-000000000001'$q$) = 1;
select '11 H3 inactive et cliente : ni mission, ni publication interne, ni ressource', pg_temp.compte(:'U3', $q$select count(*) from bsh_missions$q$) = 0 and pg_temp.compte(:'C', $q$select count(*) from bsh_missions$q$) = 0 and pg_temp.compte(:'C', $q$select count(*) from bsh_communications$q$) = 0 and pg_temp.compte(:'C', $q$select count(*) from bsh_ressources$q$) = 0;
select '12 hôte : modification directe de la mission refusée (aucune ligne modifiée)', pg_temp.compte(:'U1', $q$with u as (update bsh_missions set consignes='piratage', statut_execution='realisee' returning 1) select count(*) from u$q$) = 0;
select '13 hôte : report et annulation refusés (réservés à la fondatrice)', pg_temp.essai(:'U1', $q$select bsh_hote_execution('e0000000-0000-0000-0000-000000000001','reportee','Je reporte à demain svp')$q$) = 'refusé' and pg_temp.essai(:'U1', $q$select bsh_hote_execution('e0000000-0000-0000-0000-000000000001','annulee','Annulation de mon fait')$q$) = 'refusé';
select '14 hôte : « réalisée » sans compte rendu refusée ; avec compte rendu acceptée', pg_temp.essai(:'U2', $q$select bsh_hote_execution('e0000000-0000-0000-0000-000000000001','realisee','ok')$q$) = 'refusé' and pg_temp.essai(:'U2', $q$select bsh_hote_execution('e0000000-0000-0000-0000-000000000001','realisee','Animation menée par la remplaçante, 9 participantes.')$q$) = 'accepté';
select '15 compte rendu et auteur enregistrés', (select statut_execution = 'realisee' and compte_rendu like 'Animation menée%' and execute_par = '00000000-0000-0000-0000-0000000000b2' from bsh_missions where id='e0000000-0000-0000-0000-000000000001');
select '16 hôte d''une autre mission : déclaration refusée', pg_temp.essai(:'U3', $q$select bsh_hote_execution('e0000000-0000-0000-0000-000000000001','en_cours',null)$q$) = 'refusé';
select '17 confirmation sans preuve suffisante refusée', pg_temp.essai(:'U1', $q$select bsh_confirmer_publication('a0000000-0000-0000-0000-000000000002','ok',null)$q$) = 'refusé';
select '18 H1 confirme sa publication avec preuve → publiée', pg_temp.essai(:'U1', $q$select bsh_confirmer_publication('a0000000-0000-0000-0000-000000000002','Message posté dans le Cercle à 08:03, capture conservée','https://exemple.invalid/preuve')$q$) = 'accepté';
select '18b … et la publication est bien au statut « publié »', (select statut from bsh_communications where id='a0000000-0000-0000-0000-000000000002') = 'publie';
select '19 hôte : confirmation d''une publication qui ne lui est pas confiée refusée', pg_temp.essai(:'U1', $q$select bsh_confirmer_publication('a0000000-0000-0000-0000-000000000001','Je déclare cette publication faite',null)$q$) = 'refusé';
select '20 fondatrice confirme P1 avec preuve → publiée ; preuve tracée (source, auteur)', pg_temp.essai(:'F', $q$select bsh_confirmer_publication('a0000000-0000-0000-0000-000000000001','Lien du message de la Chaîne BSH, 08:01',null)$q$) = 'accepté';
select '20b … preuves tracées : 1 de la fondatrice, 1 de l''hôte, avec leur auteur', (select count(*) from bsh_preuves_publication where source='fondatrice' and confirme_par='00000000-0000-0000-0000-0000000000f1') = 1 and (select count(*) from bsh_preuves_publication where source='hote' and confirme_par='00000000-0000-0000-0000-0000000000b1') = 1;
select '21 publication confirmée : retour en « programmé » refusé', pg_temp.essai(:'F', $q$update bsh_communications set statut='programme' where id='a0000000-0000-0000-0000-000000000001'$q$) = 'refusé';
select '22 visiteur anonyme : lit les 2 textes publiés, mais plus les notes internes ni l''hôte', pg_temp.compte_anon($q$select count(*) from (select id, titre, contenu from bsh_communications) x$q$) = 2 and pg_temp.compte_anon($q$select count(*) from (select notes_internes from bsh_communications) x$q$) = -1 and pg_temp.compte_anon($q$select count(*) from (select hote_id from bsh_communications) x$q$) = -1;
select '23 anonyme : aucune preuve, ressource, création ni version', pg_temp.compte_anon($q$select count(*) from bsh_preuves_publication$q$) = -1 and pg_temp.compte_anon($q$select count(*) from bsh_ressources$q$) = -1 and pg_temp.compte_anon($q$select count(*) from bsh_creations$q$) = -1;
select '24 hôte : insertion directe d''une preuve refusée', pg_temp.essai(:'U1', $q$insert into bsh_preuves_publication(communication_id,preuve) values ('a0000000-0000-0000-0000-000000000002','fausse preuve directe')$q$) = 'refusé';
