select '27 studio : création + 2 versions numérotées automatiquement', pg_temp.essai(:'F', $q$insert into bsh_creations(id,titre,format,ambiance) values ('f0000000-0000-0000-0000-000000000001','Affiche 1er décembre','affiche','dark_romance'); insert into bsh_creations_versions(creation_id,contenu) values ('f0000000-0000-0000-0000-000000000001','{"titre":"V1"}'); insert into bsh_creations_versions(creation_id,contenu,note_correction) values ('f0000000-0000-0000-0000-000000000001','{"titre":"V2"}','Titre plus court')$q$) = 'accepté';
select '27b … version courante = 2, numéros 1 et 2', (select version_courante from bsh_creations where id='f0000000-0000-0000-0000-000000000001') = 2 and (select string_agg(numero::text, ',' order by numero) from bsh_creations_versions) = '1,2';
select '28 studio : une version ne se modifie ni ne se supprime', pg_temp.essai(:'F', $q$update bsh_creations_versions set contenu='{}' where numero=1$q$) = 'refusé' and pg_temp.essai(:'F', $q$delete from bsh_creations_versions where numero=1$q$) = 'refusé';
select '29 studio : variante liée à sa création d''origine', pg_temp.essai(:'F', $q$insert into bsh_creations(titre,format,parent_id) values ('Affiche 1er décembre – variante story','story','f0000000-0000-0000-0000-000000000001')$q$) = 'accepté';
select '30 hôte et cliente : aucun accès au studio', pg_temp.compte(:'U1', $q$select count(*) from bsh_creations$q$) = 0 and pg_temp.compte(:'C', $q$select count(*) from bsh_creations_versions$q$) = 0;
